const D = { energy: .62, density: .5, speed: 1, scale: 1, spread: .5, climb: .5, hue: 44, x: .5, y: .5, style: 'ink', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const st = P.style, u = Math.min(width, height);
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return s - Math.floor(s); };

// palette / ground per style
let ground, plateEdge, baseHue, dark;
if (st === 'uv')        { ground = [122,46,26]; plateEdge = [122,30,40]; baseHue = 300; dark = true; }
else if (st === 'silica') { ground = [40,20,52]; plateEdge = [38,25,64]; baseHue = ((P.hue%360)+360)%360; dark = false; }
else if (st === 'blueprint'){ ground = [212,58,12]; plateEdge = [196,60,55]; baseHue = 196; dark = true; }
else if (st === 'densitometry'){ ground = [230,30,9]; plateEdge = [200,40,50]; baseHue = 190; dark = true; }
else /* ink */          { ground = [250,42,10]; plateEdge = [250,30,26]; baseHue = ((P.hue%360)+360)%360; dark = true; }

const lanes = Math.max(4, Math.round(4 + P.density*8));   // 4..12
if (S.seedUsed !== P.seed || S.lanes !== lanes || S.stKey !== st) {
  S.seedUsed = P.seed; S.lanes = lanes; S.stKey = st;
  S.lane = [];
  for (let l = 0; l < lanes; l++) {
    const nc = 3 + Math.floor(fr(l*3.7)*3);               // 3..5 components
    const comps = [];
    for (let c = 0; c < nc; c++) {
      const rf = 0.14 + fr(l*7.1 + c*2.9)*0.82;           // retention factor
      const hue = st === 'silica' ? [96,36,54,20,140][c % 5] + fr(l+c)*18
                 : (baseHue + c*68 + fr(l*2+c)*40) % 360; // pigment hues
      comps.push({ rf, hue, sat: 62 + fr(l*5+c)*32, size: 0.7 + fr(l*9+c)*0.8, sd: fr(l*11+c) });
    }
    comps.sort((a,b) => a.rf - b.rf);
    S.lane.push({ comps, phase: fr(l*4.3) });
  }
}

// ── plate ground (static, adaptive buffer) ──
const BW = Math.max(360, Math.min(680, Math.round(width/2.4)));
const BH = Math.max(160, Math.round(BW*height/width));
const bkey = BW+'x'+BH+'|'+st+'|'+P.seed+'|'+lanes;
if (!S.bg || S.bkey !== bkey) {
  S.bkey = bkey; const g = S.bg || (S.bg = createGraphics(BW, BH));
  g.colorMode(g.HSB,360,100,100,100); g.pixelDensity(1); g.noStroke(); g.push();
  for (let y = 0; y < BH; y++) { const f = y/BH; g.fill(ground[0], ground[1], ground[2]*(0.85+0.3*(1-f)), 100); g.rect(0,y,BW,1); }
  g.blendMode(g.ADD);
  for (let i = 0; i < 240; i++) { const x=fr(i*1.7)*BW, y=fr(i*2.9+3)*BH, r=(3+fr(i*3.3)*14)*(BW/500);
    g.fill(ground[0], ground[1]*0.5, ground[2]+10, dark?2.5:3.5); g.ellipse(x,y,r,r); }
  g.blendMode(g.BLEND);
  g.stroke(ground[0], ground[1]*0.4, ground[2]*0.5, 30); g.strokeWeight(1);
  const lw = BW/lanes; for (let l=1;l<lanes;l++) g.line(l*lw,0,l*lw,BH);
  g.pop();
}

push();
image(S.bg, 0, 0, width, height);

// ── geometry + continuous elution ──
const baseline = height*0.90, topM = height*0.10, maxRise0 = baseline - topM;
const laneW = width/lanes;
const tNow = Math.max(0, K.t) * (0.16 + 0.3*P.speed);
const injPeriod = 3.2;
const maxRise = maxRise0 * (0.55 + P.climb*0.45);
const sep = 0.6 + P.spread*0.9;                          // Rf separation amplitude
const spotBrt = 0.5 + P.energy*0.7, gShimmer = 0.85 + K.pulse*0.3 + A.rms*0.5;
const drift = 0.5*Math.sin(K.t*0.61) + 0.35*Math.sin(K.t*1.43+1.1);

// decorative solvent front (gentle bob, no seam)
const frontY = topM + Math.sin(K.t*0.19)*height*0.012 + Math.sin(K.t*0.37+1.0)*height*0.006;
blendMode(BLEND); noStroke();
fill(plateEdge[0], plateEdge[1]*0.5, plateEdge[2], dark?12:18); rect(0, frontY, width, baseline-frontY); // wet region tint
stroke(plateEdge[0], plateEdge[1], plateEdge[2]+10, dark?40:55); strokeWeight(1.4); line(0, frontY, width, frontY);
// baseline (pencil origin line)
stroke(0,0, dark?70:26, dark?36:55); strokeWeight(1.2); line(0, baseline, width, baseline);
noStroke();

blendMode(dark ? ADD : BLEND);
for (let l = 0; l < lanes; l++) {
  const xc = (l+0.5)*laneW, ln = S.lane[l];
  const k0 = Math.floor(tNow / injPeriod);
  for (let kk = k0; kk >= k0-1; kk--) {
    if (kk < 0) continue;
    const age = tNow - (kk*injPeriod + ln.phase*injPeriod);
    if (age < 0) continue;
    const front = maxRise * (1 - Math.exp(-age*0.7));
    // lifetime envelope: rise in, settle, fade out to refresh lane
    let life = 1;
    if (age < 0.5) life = age/0.5;
    else if (age > 3.6) life = Math.max(0, (4.6 - age)/1.0);
    if (life <= 0) continue;
    for (let c = 0; c < ln.comps.length; c++) {
      const cp = ln.comps[c];
      const rfEff = 0.5 + (cp.rf - 0.5)*sep;               // spread param stretches separation
      const y = baseline - Math.max(0, Math.min(1, rfEff)) * front;
      const diff = 1 + age*0.5;                            // spot diffuses/tails as it climbs
      const rw = u*0.020*cp.size*P.scale*diff;
      const rh = rw*(1.0 + age*0.28);                      // vertical tailing
      const wob = Math.sin(K.t*0.8 + c*1.9 + l + drift)*laneW*0.03;
      const a = Math.min(100, 92*spotBrt*life*gShimmer*(0.7+cp.sd*0.5));
      if (a < 1) continue;
      const isBlue = (st==='blueprint'||st==='densitometry');
      const hh = isBlue ? baseHue : cp.hue, ss = isBlue ? 55 : cp.sat, bb = isBlue ? 90 : (dark? 92 : 78);
      if (st === 'densitometry') {
        fill(hh, ss, bb, a*0.5); rect(xc-laneW*0.4, y-1.5, laneW*0.8*(0.3+cp.rf*0.6), 3);
      } else if (st === 'blueprint') {
        noFill(); stroke(hh, ss, bb, a); strokeWeight(1.3); ellipse(xc+wob, y, rw*2.2, rh*2.2); noStroke();
        fill(hh, ss, bb, a*0.5); ellipse(xc+wob, y, 3, 3);
      } else {
        fill(hh, ss*0.85, bb, a*0.28); ellipse(xc+wob, y, rw*2.6, rh*2.6);       // halo
        fill(hh, ss, bb, a*0.8); ellipse(xc+wob, y, rw*1.5, rh*1.5);             // mid
        fill(hh, Math.min(100,ss+8), Math.min(100,bb+6), a); ellipse(xc+wob, y, rw, rh); // core
      }
    }
  }
}
pop();
blendMode(BLEND); noTint(); drawingContext.shadowBlur = 0;
if (P.alpha < 100) { push(); noStroke(); fill(0,0,0,100-P.alpha); rect(0,0,width,height); pop(); }
